import java.util.Scanner;
public class JStars1
{
	public static void main (String[] args)
	{		
		//Paso 1: Leer el numero de filas del patron de estrellas en triangulo recto
		Scanner scan = new Scanner(System.in);
		System.out.println("Ingrese el numero de filas del patron de estrellas en triangulo recto: ");
		int N = scan.nextInt();
		scan.close();
		//Paso 2: Imprimir las filas del patron de estrellas, una por una
		for (int i = 1; i <= N; i++)
		{
			//Paso 2.1: Imprimir los asteriscos en la i-esima fila
			for (int j = 1; j <= i; j++) {
				System.out.print("*");
			}
			System.out.println();
		}
	}
}

